//! Queue groups, declared in [`topics!`](crate::topics) with `[ … ]`.

use crate::tree::DynValue;
use std::hash::{Hash, Hasher};
use std::sync::Arc;

/// A group enum generated by [`topics!`](crate::topics), joined with
/// [`queue`](crate::SubscriptionBuilder::queue). Each value is one queue
/// group: `Indexer(0)` and `Indexer(1)` are two groups.
#[diagnostic::on_unimplemented(
    message = "`{Self}` isn't a queue group",
    note = "declare queue groups in `topics!` with `[ … ]` after a topic's name"
)]
pub trait QueueGroup: Eq + Hash + Send + Sync + 'static {}

/// The group enum `Self` is declared on the topic whose channels have the type
/// `T` (its `Topic` enum or leaf type), so it can be joined there.
#[diagnostic::on_unimplemented(
    message = "queue group `{Self}` isn't declared on `{T}`",
    note = "a queue group is joined on the topic that declares it"
)]
pub trait InScope<T> {}

/// A queue group value, compared by type and value.
#[derive(Clone)]
pub(crate) struct GroupKey(Arc<dyn DynValue>);

impl PartialEq for GroupKey {
    fn eq(&self, other: &Self) -> bool {
        *self.0 == *other.0
    }
}

impl Eq for GroupKey {}

impl Hash for GroupKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.0.hash(state);
    }
}

impl GroupKey {
    pub(crate) fn new(group: impl QueueGroup) -> Self {
        Self(Arc::new(group))
    }
}

/// The group's type: group values need not implement `Debug`.
#[cfg(feature = "tracing")]
impl std::fmt::Debug for GroupKey {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str((*self.0).type_name())
    }
}
